alter table pw_player add column max_active_orders integer not null default 1;
update pw_dispatch_rule set max_active_orders=20 where max_active_orders=1;
alter table pw_order add column completion_submitted_at timestamp;
create table pw_fulfillment (id bigint generated by default as identity primary key,order_id bigint not null unique,player_id bigint not null,fulfillment_status varchar(24) not null default 'IN_SERVICE',completion_note varchar(1000),actual_quantity decimal(10,2),submitted_at timestamp,reviewed_by bigint,reviewed_at timestamp,review_remark varchar(500),created_at timestamp not null default current_timestamp,updated_at timestamp not null default current_timestamp);
create index ix_pw_fulfillment_player on pw_fulfillment(player_id,fulfillment_status);
create table pw_fulfillment_proof (id bigint generated by default as identity primary key,fulfillment_id bigint not null,proof_type varchar(16) not null,proof_url varchar(512) not null,sort_no integer not null default 0,created_at timestamp not null default current_timestamp);
create table pw_fulfillment_audit (id bigint generated by default as identity primary key,fulfillment_id bigint not null,action varchar(16) not null,before_status varchar(24),after_status varchar(24) not null,remark varchar(500),operator_id bigint,created_at timestamp not null default current_timestamp);
insert into sys_menu(parent_id,type,name,path,component,title,icon,sort_no) select id,'MENU','FulfillmentReview','fulfillment-review','/business/fulfillment-review','履约审核','ri:shield-check-line',9 from sys_menu where name='Business' and not exists(select 1 from sys_menu where name='FulfillmentReview');
insert into sys_menu(parent_id,type,name,title,auth_mark,sort_no) select p.id,'BUTTON',concat(p.name,a.suffix),a.title,a.mark,a.sort_no from sys_menu p join (select 'List' suffix,'查询履约记录' title,'business:fulfillment:list' mark,1 sort_no union all select 'Detail','查看履约详情','business:fulfillment:detail',2 union all select 'Review','审核完成凭证','business:fulfillment:review',3) a on 1=1 where p.name='FulfillmentReview' and not exists(select 1 from sys_menu m where m.auth_mark=a.mark);
insert into sys_menu(parent_id,type,name,title,auth_mark,sort_no) select p.id,'BUTTON','PlayerWorkbenchOrderStart','开始服务','player:order:start',8 from sys_menu p where p.name='PlayerWorkbench' and not exists(select 1 from sys_menu where auth_mark='player:order:start');
insert into sys_menu(parent_id,type,name,title,auth_mark,sort_no) select p.id,'BUTTON','PlayerWorkbenchOrderSubmit','提交完成凭证','player:order:submit',9 from sys_menu p where p.name='PlayerWorkbench' and not exists(select 1 from sys_menu where auth_mark='player:order:submit');
insert into sys_role_menu(role_id,menu_id) select r.id,m.id from sys_role r cross join sys_menu m where r.code='admin' and (m.name='FulfillmentReview' or m.auth_mark like 'business:fulfillment:%' or m.auth_mark in('player:order:start','player:order:submit')) and not exists(select 1 from sys_role_menu x where x.role_id=r.id and x.menu_id=m.id);
insert into sys_role_menu(role_id,menu_id) select r.id,m.id from sys_role r cross join sys_menu m where r.code='player' and m.auth_mark in('player:order:start','player:order:submit') and not exists(select 1 from sys_role_menu x where x.role_id=r.id and x.menu_id=m.id);
